@php
    $rows = collect($gradingScales ?? $grading ?? []);
    $details = $gradingDetails ?? collect();
    $filters = $filters ?? ['search' => '', 'name' => '', 'from' => '', 'to' => ''];
    $names = collect($gradingNames ?? $rows)->pluck('name')->filter()->unique()->sort()->values();
